class Solution {
public:
    vector<string> mostVisitedPattern(vector<string>& username,
                                      vector<int>& timestamp,
                                      vector<string>& website) {
        int n = username.size();
        vector<int> order(n);
        iota(order.begin(), order.end(), 0);
        sort(order.begin(), order.end(), [&](int a, int b) {
            return timestamp[a] < timestamp[b];
        });
        map<string, vector<string>> visits;
        for (int index : order) {
            visits[username[index]].push_back(website[index]);
        }
        map<vector<string>, int> frequency;
        for (const auto& item : visits) {
            const auto& sites = item.second;
            set<vector<string>> unique;
            for (int i = 0; i < static_cast<int>(sites.size()); ++i) {
                for (int j = i + 1; j < static_cast<int>(sites.size()); ++j) {
                    for (int k = j + 1; k < static_cast<int>(sites.size()); ++k) {
                        unique.insert({sites[i], sites[j], sites[k]});
                    }
                }
            }
            for (const auto& pattern : unique) {
                ++frequency[pattern];
            }
        }
        vector<string> answer;
        int best = -1;
        for (const auto& item : frequency) {
            if (item.second > best) {
                best = item.second;
                answer = item.first;
            }
        }
        return answer;
    }
};
